from typing import Dict, Any, List, Optional, Union
from meilisearch import Client


class DocumentManager:
    """Manage documents within Meilisearch indexes"""

    def __init__(self, client: Client):
        self.client = client

    def get_documents(
        self,
        index_uid: str,
        offset: Optional[int] = None,
        limit: Optional[int] = None,
        fields: Optional[List[str]] = None,
    ) -> Dict[str, Any]:
        """Get documents from an index"""
        try:
            index = self.client.index(index_uid)
            # Build parameters dict, excluding None values to avoid API errors
            params = {}
            if offset is not None:
                params["offset"] = offset
            if limit is not None:
                params["limit"] = limit
            if fields is not None:
                params["fields"] = fields

            result = index.get_documents(params if params else {})

            # Convert meilisearch model objects to JSON-serializable format
            if hasattr(result, "__dict__"):
                result_dict = result.__dict__.copy()
                # Convert individual document objects in results if they exist
                if "results" in result_dict and isinstance(
                    result_dict["results"], list
                ):
                    serialized_results = []
                    for doc in result_dict["results"]:
                        if hasattr(doc, "__dict__"):
                            # Extract the actual document data
                            doc_dict = doc.__dict__.copy()
                            # Look for private attributes that might contain the actual data
                            for key, value in doc_dict.items():
                                if key.startswith("_") and isinstance(value, dict):
                                    # Use the dict content instead of the wrapper
                                    serialized_results.append(value)
                                    break
                            else:
                                # If no private dict found, use the object dict directly
                                serialized_results.append(doc_dict)
                        else:
                            serialized_results.append(doc)
                    result_dict["results"] = serialized_results
                return result_dict
            else:
                return result
        except Exception as e:
            raise Exception(f"Failed to get documents: {str(e)}")

    def get_document(
        self, index_uid: str, document_id: Union[str, int]
    ) -> Dict[str, Any]:
        """Get a single document"""
        try:
            index = self.client.index(index_uid)
            return index.get_document(document_id)
        except Exception as e:
            raise Exception(f"Failed to get document: {str(e)}")

    def add_documents(
        self,
        index_uid: str,
        documents: List[Dict[str, Any]],
        primary_key: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Add documents to an index"""
        try:
            index = self.client.index(index_uid)
            return index.add_documents(documents, primary_key)
        except Exception as e:
            raise Exception(f"Failed to add documents: {str(e)}")

    def update_documents(
        self, index_uid: str, documents: List[Dict[str, Any]]
    ) -> Dict[str, Any]:
        """Update documents in an index"""
        try:
            index = self.client.index(index_uid)
            return index.update_documents(documents)
        except Exception as e:
            raise Exception(f"Failed to update documents: {str(e)}")

    def delete_document(
        self, index_uid: str, document_id: Union[str, int]
    ) -> Dict[str, Any]:
        """Delete a single document"""
        try:
            index = self.client.index(index_uid)
            return index.delete_document(document_id)
        except Exception as e:
            raise Exception(f"Failed to delete document: {str(e)}")

    def delete_documents(
        self, index_uid: str, document_ids: List[Union[str, int]]
    ) -> Dict[str, Any]:
        """Delete multiple documents by ID"""
        try:
            index = self.client.index(index_uid)
            return index.delete_documents(document_ids)
        except Exception as e:
            raise Exception(f"Failed to delete documents: {str(e)}")

    def delete_all_documents(self, index_uid: str) -> Dict[str, Any]:
        """Delete all documents in an index"""
        try:
            index = self.client.index(index_uid)
            return index.delete_all_documents()
        except Exception as e:
            raise Exception(f"Failed to delete all documents: {str(e)}")

import logging
from meilisearch import Client
from typing import Optional, Dict, Any, List

from .indexes import IndexManager
from .documents import DocumentManager
from .tasks import TaskManager
from .settings import SettingsManager
from .keys import KeyManager
from .monitoring import MonitoringManager
from .__version__ import __version__

logger = logging.getLogger(__name__)


class MeilisearchClient:
    def __init__(
        self, url: str = "http://localhost:7700", api_key: Optional[str] = None
    ):
        """Initialize Meilisearch client"""
        self.url = url
        self.api_key = api_key
        # Add custom user agent to identify this as Meilisearch MCP
        self.client = Client(
            url, api_key, client_agents=("meilisearch-mcp", f"v{__version__}")
        )
        self.indexes = IndexManager(self.client)
        self.documents = DocumentManager(self.client)
        self.settings = SettingsManager(self.client)
        self.tasks = TaskManager(self.client)
        self.keys = KeyManager(self.client)
        self.monitoring = MonitoringManager(self.client)

    def health_check(self) -> bool:
        """Check if Meilisearch is healthy"""
        try:
            response = self.client.health()
            return response.get("status") == "available"
        except Exception:
            return False

    def get_version(self) -> Dict[str, Any]:
        """Get Meilisearch version information"""
        return self.client.get_version()

    def get_stats(self) -> Dict[str, Any]:
        """Get database stats"""
        return self.client.get_all_stats()

    def search(
        self,
        query: str,
        index_uid: Optional[str] = None,
        limit: Optional[int] = 20,
        offset: Optional[int] = 0,
        filter: Optional[str] = None,
        sort: Optional[List[str]] = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Search through Meilisearch indices.
        If index_uid is provided, search in that specific index.
        If not provided, search across all available indices.
        """
        try:
            # Prepare search parameters, removing None values
            search_params = {
                "limit": limit if limit is not None else 20,
                "offset": offset if offset is not None else 0,
            }

            if filter is not None:
                search_params["filter"] = filter
            if sort is not None:
                search_params["sort"] = sort

            # Add any additional parameters
            search_params.update({k: v for k, v in kwargs.items() if v is not None})

            if index_uid:
                # Search in specific index
                index = self.client.index(index_uid)
                return index.search(query, search_params)
            else:
                # Search across all indices
                results = {}
                indexes = self.client.get_indexes()

                for index in indexes["results"]:
                    try:
                        search_result = index.search(query, search_params)
                        if search_result["hits"]:  # Only include indices with matches
                            results[index.uid] = search_result
                    except Exception as e:
                        logger.warning(f"Failed to search index {index.uid}: {str(e)}")
                        continue

                return {"multi_index": True, "query": query, "results": results}

        except Exception as e:
            raise Exception(f"Search failed: {str(e)}")

    def get_indexes(self) -> Dict[str, Any]:
        """Get all indexes"""
        indexes = self.client.get_indexes()
        # Convert Index objects to serializable dictionaries
        serialized_indexes = []
        for index in indexes["results"]:
            serialized_indexes.append(
                {
                    "uid": index.uid,
                    "primaryKey": index.primary_key,
                    "createdAt": index.created_at,
                    "updatedAt": index.updated_at,
                }
            )

        return {
            "results": serialized_indexes,
            "offset": indexes["offset"],
            "limit": indexes["limit"],
            "total": indexes["total"],
        }
